package com.funnywork;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=${FUNNYWORK_TEST_DB_URL:jdbc:h2:mem:office-tools;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1}","spring.datasource.username=${FUNNYWORK_TEST_DB_USER:sa}","spring.datasource.password=${FUNNYWORK_TEST_DB_PASSWORD:}","funnywork.bootstrap-token=","funnywork.scheduling-enabled=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class OfficeToolsIntegrationTest {
 @Autowired org.springframework.test.web.servlet.MockMvc http;@Autowired OfficeCapabilities capability;@Autowired OfficeTools office;@Autowired ControlService control;@Autowired AuthService auth;@Autowired ToolRegistry registry;@Autowired ArtifactService artifacts;
 Identity admin,owner,node,other;String agent,task,attempt;long epoch;List<String> ids;
 Identity user(String tenant,String role){String token=AuthService.id();auth.create(AuthService.id(),tenant,"USER",role,Set.of(role),Set.of("sandbox"),token);return auth.authenticate(token);}
 @BeforeEach @SuppressWarnings("unchecked") void setup(){String tenant=AuthService.id();admin=user(tenant,"ADMIN");owner=user(tenant,"OPERATOR");other=user(AuthService.id(),"ADMIN");agent=(String)control.publishAgent(admin,new Requests.Agent("office","1.0.0","model.read.v1")).get("agentId");ids=(List<String>)capability.configure(admin,new OfficeCapabilities.Configure(agent,"sandbox","1.0.0")).get("tools");task=(String)control.createTask(owner,AuthService.id(),new Requests.Task(agent,"sandbox",List.of("create office"))).get("taskId");node=auth.authenticate((String)control.registerNode(admin,new Requests.Node("Office","sandbox",1,"model.read.v1")).get("token"));control.heartbeat(node,true);control.tick();var work=control.poll(node);attempt=(String)work.get("attemptId");epoch=((Number)work.get("epoch")).longValue();}
 OfficeTools.Call request(Map<String,Object> args){return new OfficeTools.Call(epoch,AuthService.hash(args.toString()),args);}
 @Test void draftsAreTaskBoundIdempotentAndEditsPreserveOriginal(){var call=request(Map.of("name","report.docx","format","docx","documentJson","{\"paragraphs\":[\"原始内容\"]}"));var created=office.call(node,attempt,ids.get(2),call);assertEquals(created,office.call(node,attempt,ids.get(2),call));String id=(String)created.get("artifactId");assertEquals(false,created.get("businessVerified"));assertEquals(1,((List<?>)office.outputs(owner,task,"",50).get("items")).size());
  var read=request(Map.of("artifactId",id,"version",1,"offset",0,"limit",20));assertTrue(office.call(node,attempt,ids.get(1),read).toString().contains("原始内容"));var edit=request(Map.of("artifactId",id,"version",1,"documentJson","{\"operations\":[{\"type\":\"replaceParagraph\",\"paragraph\":0,\"text\":\"修订内容\"}]}"));var revised=office.call(node,attempt,ids.get(3),edit);assertNotEquals(id,revised.get("artifactId"));assertTrue(office.preview(owner,id,1,0,20,0).toString().contains("原始内容"));assertTrue(office.preview(owner,(String)revised.get("artifactId"),1,0,20,0).toString().contains("修订内容"));assertEquals(403,assertThrows(ApiException.class,()->office.preview(other,id,1,0,20,0)).status);
  var conflict=new OfficeTools.Call(epoch,call.requestKey(),Map.of("name","other.docx","format","docx","documentJson","{\"paragraphs\":[\"改写\"]}"));assertEquals(409,assertThrows(ApiException.class,()->office.call(node,attempt,ids.get(2),conflict)).status);registry.disable(admin,ids.get(2));assertThrows(ApiException.class,()->office.call(node,attempt,ids.get(2),call));
 }
 @Test void upgradeReplacesDefaultsButKeepsRunningTaskSnapshot(){capability.configure(admin,new OfficeCapabilities.Configure(agent,"sandbox","2.0.0"));capability.configure(admin,new OfficeCapabilities.Configure(agent,"sandbox","2.0.0"));var status=capability.status(admin,agent,"sandbox");assertEquals(1,((List<?>)status.get("skills")).size());assertEquals(3,office.catalog(node,attempt,epoch).size());assertTrue(office.catalog(node,attempt,epoch).contains(ids.get(2)));assertEquals(403,assertThrows(ApiException.class,()->capability.configure(owner,new OfficeCapabilities.Configure(agent,"sandbox","3.0.0"))).status);}
 @Test void httpOfficeUploadAllowsLargeEnvelopeWhileOtherRoutesRemainBounded()throws Exception{String token=AuthService.id();auth.create(AuthService.id(),owner.tenant(),"USER","Upload",Set.of("OPERATOR"),Set.of("sandbox"),token);String content=Base64.getEncoder().encodeToString(new byte[900000]);http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/artifacts").header("Authorization","Bearer "+token).contentType("application/json").content("{\"name\":\"large.docx\",\"zone\":\"sandbox\",\"contentBase64\":\""+content+"\"}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/chats").header("Authorization","Bearer "+token).contentType("application/json").content(" ".repeat(1048577))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isPayloadTooLarge());}
 @Test void officeUploadLimitDoesNotExpandGenericTextLimit(){String content=Base64.getEncoder().encodeToString(new byte[270000]);var file=artifacts.create(owner,new ArtifactService.Create("uploaded.docx","sandbox",content));assertEquals(270000,((Number)artifacts.read(owner,(String)file.get("artifactId"),1).get("byte_size")).intValue());assertEquals(413,assertThrows(ApiException.class,()->artifacts.create(owner,new ArtifactService.Create("generic.txt","sandbox",content))).status);assertEquals(413,assertThrows(ApiException.class,()->artifacts.create(owner,new ArtifactService.Create("oversized.xlsx","sandbox",Base64.getEncoder().encodeToString(new byte[2097153])))).status);}
 @Test void unattachedSourceCannotBeRead(){var bytes=new OfficeDocuments(new com.fasterxml.jackson.databind.ObjectMapper()).create("docx","{\"paragraphs\":[\"未附加\"]}");String id=(String)artifacts.create(owner,new ArtifactService.Create("source.docx","sandbox",Base64.getEncoder().encodeToString(bytes))).get("artifactId");assertEquals(404,assertThrows(ApiException.class,()->office.call(node,attempt,ids.get(1),request(Map.of("artifactId",id,"version",1,"offset",0,"limit",20)))).status);assertThrows(ApiException.class,()->office.catalog(node,attempt,epoch+1));}
}
